// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/random_number_generator.sol";

contract PredictableRandomTest is Test {
    RandomNumberGenerator public game;
    address public player = makeAddr("player");

    function setUp() public {
        game = new RandomNumberGenerator();
    }

    function testRandomIsPredictable() public {
        // Fix the block number to remove environment randomness
        uint256 blockNumber = 10;
        vm.roll(blockNumber);

        // First game play (record result via event)
        vm.prank(player);
        vm.recordLogs();
        game.playGame(1);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // Extract winning number from WinningNumberSet event
        bytes32 winningNumberEventTopic = keccak256("WinningNumberSet(uint256)");
        uint256 firstResult;
        for (uint256 i; i < logs.length; i++) {
            if (logs[i].topics[0] == winningNumberEventTopic) {
                firstResult = abi.decode(logs[i].data, (uint256));
                break;
            }
        }

        // Second game play in SAME BLOCK
        vm.prank(player);
        vm.recordLogs();
        game.playGame(1);
        logs = vm.getRecordedLogs();

        // Extract second winning number
        uint256 secondResult;
        for (uint256 i; i < logs.length; i++) {
            if (logs[i].topics[0] == winningNumberEventTopic) {
                secondResult = abi.decode(logs[i].data, (uint256));
                break;
            }
        }

        // Verify identical "random" results
        assertEq(
            firstResult,
            secondResult,
            "Random numbers should be identical in same block"
        );
    }
}
